import {
  MjmlColumn,
  MjmlGroup,
  MjmlImage,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  Mjml,
  MjmlBody,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlStyle,
  MjmlWrapper,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type AvatarSize = "2xl" | "lg" | "md" | "sm" | "xl" | "xs";

interface InternalAvatarItem {
  name: string;
  url?: string;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const avatarResponsiveStyles = `
  .emailcn-avatar-group-left { margin-left: 0 !important; margin-right: auto !important; }
  .emailcn-avatar-group-center { margin-left: auto !important; margin-right: auto !important; }
  .emailcn-avatar-group-right { margin-left: auto !important; margin-right: 0 !important; }
`;

const defaultAvatars: InternalAvatarItem[] = [
  { name: "John Adams", url: emailAsset(`reviews/avatar-2.jpg`) },
  { name: "Sarah Wilson", url: emailAsset(`reviews/avatar.jpg`) },
  { name: "Michael Chen", url: emailAsset(`reviews/avatar-4.jpg`) },
  { name: "Emily Davis", url: emailAsset(`reviews/avatar-5.jpg`) },
];

const avatarSizes: Record<
  AvatarSize,
  {
    countFontSize: number;
    diameter: number;
    overlapWidth: number;
  }
> = {
  "2xl": { countFontSize: 20, diameter: 64, overlapWidth: 48 },
  lg: { countFontSize: 16, diameter: 48, overlapWidth: 36 },
  md: { countFontSize: 14, diameter: 40, overlapWidth: 30 },
  sm: { countFontSize: 14, diameter: 32, overlapWidth: 24 },
  xl: { countFontSize: 18, diameter: 56, overlapWidth: 42 },
  xs: { countFontSize: 11, diameter: 24, overlapWidth: 18 },
};

const AvatarShell = ({ children }: { children: ReactNode }) => (
  <>
    <MjmlSection padding="0">
      <MjmlColumn padding="0">
        <MjmlSpacer height="100px" />
      </MjmlColumn>
    </MjmlSection>
    <MjmlSection backgroundColor="#fffffe" padding="44px 24px">
      {children}
    </MjmlSection>
    <MjmlSection padding="0">
      <MjmlColumn padding="0">
        <MjmlSpacer height="100px" />
      </MjmlColumn>
    </MjmlSection>
  </>
);

const GroupedOverlappedAvatarsSection = ({
  align = "center",
  avatars = defaultAvatars,
  plusCount,
  size = "md",
}: {
  align?: "center" | "left" | "right";
  avatars?: InternalAvatarItem[];
  plusCount?: number;
  size?: AvatarSize;
}) => {
  const config = avatarSizes[size];
  const visibleAvatars = avatars.slice(0, 4);
  const itemCount =
    visibleAvatars.length + (plusCount && plusCount > 0 ? 1 : 0);
  const groupWidth =
    Math.max(0, itemCount - 1) * config.overlapWidth + config.diameter;
  return (
    <AvatarShell>
      <MjmlGroup
        cssClass={`emailcn-avatar-group-${align}`}
        verticalAlign="middle"
        width={`${groupWidth}px`}
      >
        {visibleAvatars.map((avatar, index) => (
          <MjmlColumn
            key={`${avatar.name}-${index}`}
            padding="0"
            verticalAlign="middle"
            width={`${config.overlapWidth}px`}
          >
            <MjmlImage
              alt={avatar.name}
              border="2px solid #fffffe"
              borderRadius="9999px"
              height={`${config.diameter}px`}
              padding="0"
              src={avatar.url ?? defaultAvatars[index % 4]?.url}
              width={`${config.diameter}px`}
            />
          </MjmlColumn>
        ))}
        {plusCount && plusCount > 0 ? (
          <MjmlColumn
            backgroundColor="#d1fae5"
            border="2px solid #fffffe"
            borderRadius="9999px"
            padding="0"
            verticalAlign="middle"
            width={`${config.diameter}px`}
          >
            <MjmlText
              align="center"
              color="#030712"
              fontFamily={fontFamily}
              fontSize={`${config.countFontSize}px`}
              fontWeight="500"
              lineHeight={`${config.diameter}px`}
              padding="0"
            >
              +{plusCount}
            </MjmlText>
          </MjmlColumn>
        ) : null}
      </MjmlGroup>
    </AvatarShell>
  );
};

interface Avatar_GroupedOverlappedAvatarsProps {
  align?: "center" | "left" | "right";
  avatars?: InternalAvatarItem[];
  plusCount?: number;
  size?: AvatarSize;
  theme?: EmailTheme;
}

const Avatar_GroupedOverlappedAvatars = ({
  theme = defaultTheme,
  ...props
}: Avatar_GroupedOverlappedAvatarsProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Grouped overlapped avatars</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
      <MjmlStyle>{avatarResponsiveStyles}</MjmlStyle>
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <GroupedOverlappedAvatarsSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

Avatar_GroupedOverlappedAvatars.PreviewProps = {
  avatars: defaultAvatars,
  size: "md",
  theme: defaultTheme,
} satisfies Avatar_GroupedOverlappedAvatarsProps;

const __Avatar = Avatar_GroupedOverlappedAvatars;

export interface AvatarItem {
  name: string;
  url?: string;
}

export interface AvatarGroupProps {
  theme?: Parameters<typeof __Avatar>[0]["theme"];
  avatars?: AvatarItem[];
  plusCount?: number;
  size?: "xs" | "sm" | "md" | "lg" | "xl" | "2xl";
  align?: "left" | "center" | "right";
}

export const AvatarGroup = ({
  theme,
  avatars,
  plusCount,
  size,
  align,
}: AvatarGroupProps) => (
  <__Avatar
    align={align}
    avatars={avatars}
    plusCount={plusCount}
    size={size}
    theme={theme}
  />
);

AvatarGroup.PreviewProps = {} satisfies AvatarGroupProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
